SELECT p.policy_id::TEXT AS db_key, p.title, p.type_cd, c.code_nm AS type_cd_nm, p.req_yn, p.ordr, p.use_yn FROM t_policy p LEFT JOIN t_code c ON c.code_id = p.type_cd AND c.p_code_id = 'POLICY00' WHERE p.use_yn = 'Y' AND p.type_cd = #{typeCd}
AND p.title LIKE '%' || #{searchKeyword} || '%'
ORDER BY p.type_cd, p.ordr LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM t_policy WHERE use_yn = 'Y'
AND type_cd = #{typeCd}
AND title LIKE '%' || #{searchKeyword} || '%'
